/*
 * Rotary Positional Embedding (RoPE) CUDA kernel — optimized implementation
 *
 * Applies rotary embeddings to query and key tensors.
 * For each pair (x_i, x_{i+d/2}), rotates by angle m * theta_i where:
 *   theta_i = 1 / (base^(2i/d))
 *   m = position index
 *
 * Optimization: sin/cos computed once per (batch, seq) position and shared
 * across all heads via shared memory, eliminating redundant pow+sincos calls.
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t>
__global__ __launch_bounds__(512)
void rotary_embedding_kernel(
    scalar_t* __restrict__ x,
    const int* __restrict__ positions,
    int seq_len,
    int num_heads,
    int head_dim,
    float base,
    int half_dim
) {
    int bs_idx = blockIdx.x;
    int batch = bs_idx / seq_len;
    int seq = bs_idx % seq_len;
    int tid = threadIdx.x;
    int bdim = blockDim.x;

    extern __shared__ float smem[];
    float* s_cos = smem;
    float* s_sin = smem + half_dim;

    int m = positions[batch * seq_len + seq];

    for (int i = tid; i < half_dim; i += bdim) {
        float theta = static_cast<float>(1.0 / pow(static_cast<double>(base),
                                                    (2.0 * i) / head_dim));
        float angle = static_cast<float>(m) * theta;
        double sin_d, cos_d;
        sincos(static_cast<double>(angle), &sin_d, &cos_d);
        s_cos[i] = static_cast<float>(cos_d);
        s_sin[i] = static_cast<float>(sin_d);
    }
    __syncthreads();

    int total_pairs = num_heads * half_dim;
    for (int idx = tid; idx < total_pairs; idx += bdim) {
        int pair_idx = idx % half_dim;
        int head = idx / half_dim;

        int base_idx = ((batch * seq_len + seq) * num_heads + head) * head_dim;
        int i0 = base_idx + pair_idx;
        int i1 = base_idx + pair_idx + half_dim;

        float x0 = static_cast<float>(x[i0]);
        float x1 = static_cast<float>(x[i1]);
        float cos_val = s_cos[pair_idx];
        float sin_val = s_sin[pair_idx];

        x[i0] = static_cast<scalar_t>(x0 * cos_val - x1 * sin_val);
        x[i1] = static_cast<scalar_t>(x1 * cos_val + x0 * sin_val);
    }
}

torch::Tensor agent_rotary_embedding(
    torch::Tensor x,
    torch::Tensor positions,
    double base
) {
    auto output = x.clone();
    int batch = x.size(0);
    int seq_len = x.size(1);
    int num_heads = x.size(2);
    int head_dim = x.size(3);
    int half_dim = head_dim / 2;

    int total_pairs_per_bs = num_heads * half_dim;
    int threads = min(max(total_pairs_per_bs, half_dim), 512);
    threads = ((threads + 31) / 32) * 32;
    int blocks = batch * seq_len;
    size_t smem_size = 2 * half_dim * sizeof(float);

    if (blocks == 0) return output;

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        x.scalar_type(), "rotary_embedding", [&] {
            rotary_embedding_kernel<scalar_t><<<blocks, threads, smem_size>>>(
                output.data_ptr<scalar_t>(),
                positions.data_ptr<int>(),
                seq_len, num_heads, head_dim,
                static_cast<float>(base),
                half_dim
            );
        }
    );

    return output;
}

/*
 * RMSNorm CUDA kernel — optimized implementation
 *
 * Computes: output = (x / rms(x)) * weight
 * where rms(x) = sqrt(mean(x^2) + eps)
 *
 * Optimizations:
 * - Register caching: input values cached during sum-of-squares, reused in
 *   normalization, eliminating a second global load of the input tensor.
 * - 512 threads (vs 1024): fewer warps to reduce, better ILP per thread.
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    int tid = threadIdx.x;
    int bdim = blockDim.x;

    constexpr int VEC = 4;
    float sum_sq = 0.0f;
    float reg[VEC];
    int reg_i[VEC];
    int n_loaded = 0;

    for (int i = tid; i < hidden_size; i += bdim) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
        if (n_loaded < VEC) {
            reg[n_loaded] = val;
            reg_i[n_loaded] = i;
            n_loaded++;
        }
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[16];
    int lane = tid & 31;
    int warp_id = tid >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (bdim + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (tid == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    #pragma unroll
    for (int c = 0; c < VEC; c++) {
        if (c < n_loaded) {
            float w = static_cast<float>(__ldg(&weight[reg_i[c]]));
            o[reg_i[c]] = static_cast<scalar_t>(reg[c] * rms_inv * w);
        }
    }

    for (int i = tid + VEC * bdim; i < hidden_size; i += bdim) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}

torch::Tensor agent_rmsnorm(torch::Tensor input, torch::Tensor weight, double eps) {
    auto output = torch::empty_like(input);
    int batch = input.size(0);
    int hidden = input.size(1);

    dim3 grid(batch);
    dim3 block(min(hidden, 512));

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        input.scalar_type(), "rmsnorm", [&] {
            rmsnorm_kernel<scalar_t><<<grid, block>>>(
                input.data_ptr<scalar_t>(),
                weight.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                hidden, static_cast<float>(eps)
            );
        }
    );

    return output;
}

